module.exports.resolvePermissions = function(role, parents, grants) {
  // Validate input types
  if (typeof role !== 'string' || typeof parents !== 'object' || typeof grants !== 'object') {
    throw new Error('Invalid input types');
  }

  // Validate parents object
  if (!parents || Object.keys(parents).length === 0) {
    return [];
  }

  // Validate grants object
  if (!grants || Object.keys(grants).length === 0) {
    return [];
  }

  // Normalize grants to an array of strings
  const grantSet = new Set(grants);

  // Check for unknown role
  if (!grants[role]) {
    throw new Error(`Unknown role: ${role}`);
  }

  // Check for unknown parent
  if (!parents[role]) {
    throw new Error(`Unknown parent: ${role}`);
  }

  // Build the permission set
  const result = new Set();

  // Add the role's own grants
  for (const grant of grants[role]) {
    result.add(grant);
  }

  // Recursively add grants from parents
  const visited = new Set();
  const queue = [parents[role]];

  while (queue.length > 0) {
    const currentRole = queue.shift();

    // Skip if we've already visited this role (cycle detection)
    if (visited.has(currentRole)) {
      continue;
    }
    visited.add(currentRole);

    // If the parent is an empty object, it's a root role
    if (Object.keys(parents[currentRole]).length === 0) {
      continue;
    }

    // Add parent's grants
    for (const grant of grants[currentRole]) {
      result.add(grant);
    }

    // Add children to the queue
    for (const child of parents[currentRole]) {
      if (!visited.has(child)) {
        queue.push(child);
      }
    }
  }

  // Sort the result alphabetically
  return Array.from(result).sort();
};

